import { describe, expect, it } from 'vitest';
import { ExportStore } from '../../src/render/export-store.js';
import { buildHtmlDocument, embeddedFontFaces } from '../../src/render/html-report.js';
import { markdownToHtml, renderInline } from '../../src/render/markdown.js';
import { findBrowser } from '../../src/render/pdf.js';

describe('markdownToHtml', () => {
  it('renders the subset Malja tools emit', () => {
    const html = markdownToHtml(
      [
        '# Title',
        '',
        '> Generated by malja-mcp · Source: x',
        '',
        '## Key figures',
        '| Indicator | People (2024) |',
        '| --- | --- |',
        '| refugees | 1,234 |',
        '| Year | 2024 |',
        '',
        '**Direction:** increasing',
        '**CAGR:** 1.5%',
        '',
        '- one',
        '- two',
        '',
        '---',
        '_Source: UNHCR Refugee Data Finder, https://www.unhcr.org/refugee-statistics/_',
      ].join('\n'),
    );
    expect(html).toContain('<h1>Title</h1>');
    expect(html).toContain('<blockquote><p>Generated by malja-mcp · Source: x</p></blockquote>');
    expect(html).toContain('<th>Indicator</th><th>People (2024)</th>');
    expect(html).toContain('<td>refugees</td><td class="num">1,234</td>');
    // Years are labels, not quantities.
    expect(html).toContain('<td>Year</td><td>2024</td>');
    expect(html).toContain(
      '<p><strong>Direction:</strong> increasing<br>\n<strong>CAGR:</strong> 1.5%</p>',
    );
    expect(html).toContain('<ul>\n<li>one</li>\n<li>two</li>\n</ul>');
    expect(html).toContain('<hr>');
    expect(html).toContain(
      '<em>Source: UNHCR Refugee Data Finder, <a href="https://www.unhcr.org/refugee-statistics/">https://www.unhcr.org/refugee-statistics/</a></em>',
    );
  });

  it('marks all-numeric columns (headers too) and keeps "—" as missing', () => {
    const html = markdownToHtml('| Year | Funded |\n| --- | --- |\n| 2023 | 1,000 |\n| 2024 | — |');
    expect(html).toContain('<th>Year</th><th class="num">Funded</th>');
    expect(html).toContain('<td>2024</td><td class="num">—</td>');
  });

  it('escapes HTML everywhere and only links http(s)', () => {
    const html = markdownToHtml(
      '# <img src=x onerror=alert(1)>\n\n[click](javascript:alert(1)) <script>x</script> `<b>`\n\n| a<b> | c |\n| --- | --- |\n| <i>1</i> | 2 |',
    );
    expect(html).not.toMatch(/<img|<script|<i>|<b>/);
    expect(html).toContain('&lt;img src=x onerror=alert(1)&gt;');
    expect(html).not.toContain('href="javascript');
    expect(html).toContain('<code>&lt;b&gt;</code>');
  });

  it('inlines ```svg only when trusted; mermaid becomes captioned source', () => {
    const md = '```svg\n<svg xmlns="http://www.w3.org/2000/svg"><text>x</text></svg>\n```';
    expect(markdownToHtml(md, { trustedSvg: true })).toContain('<figure class="chart"><svg');
    expect(markdownToHtml(md)).toContain('<pre><code class="language-svg">&lt;svg');
    const mermaid = markdownToHtml('```mermaid\nxychart-beta\n```', { mermaidNote: 'note' });
    expect(mermaid).toContain('<figcaption>note</figcaption>');
  });

  it('isolates English phrases (with their URL) inside Arabic lines only', () => {
    expect(
      renderInline(
        'المصدر: (UNHCR) — UNHCR Refugee Data Finder, https://www.unhcr.org/x/ · الفترة',
      ),
    ).toBe(
      'المصدر: (UNHCR) — <span dir="ltr">UNHCR Refugee Data Finder, <a href="https://www.unhcr.org/x/">https://www.unhcr.org/x/</a></span> · الفترة',
    );
    expect(renderInline('Source: UNHCR Refugee Data Finder')).toBe(
      'Source: UNHCR Refugee Data Finder',
    );
    // Single tokens and code lists are left to the bidi algorithm.
    expect(renderInline('عبر `a`, `b` و malja-mcp')).not.toContain('<span');
    // Private-use sentinels in the input cannot inject markup.
    expect(renderInline('x\uE001y\uE002 \uE0000\uE000')).toBe('xy 0');
  });

  it('italic markers do not split identifiers like refugee_population', () => {
    expect(renderInline('_see refugee_population first._')).toBe(
      '<em>see refugee_population first.</em>',
    );
  });
});

describe('buildHtmlDocument', () => {
  const base = {
    title: 'تقرير <x>',
    bodyHtml: '<p>نص</p>',
    lang: 'ar',
    dir: 'rtl' as const,
    generator: 'malja-mcp/test',
    footer: 'footer',
  };

  it('is a self-contained RTL document with the Zad font embedded', () => {
    const html = buildHtmlDocument(base);
    expect(html.startsWith('<!doctype html>\n<html lang="ar" dir="rtl">')).toBe(true);
    expect(html).toContain('<title>تقرير &lt;x&gt;</title>');
    expect(html).toContain("font-family:'Zad'");
    expect(html).toContain('src:url(data:font/woff2;base64,');
    expect(html).toContain('@page{size:A4');
    expect(html).not.toMatch(/<link|<script src|https?:\/\/fonts/);
    expect(embeddedFontFaces().match(/@font-face/g)).toHaveLength(2);
    expect(buildHtmlDocument({ ...base, embedFont: false })).not.toContain('data:font/woff2');
  });

  it('appends the manifest as a table plus script-safe JSON', () => {
    const html = buildHtmlDocument({
      ...base,
      manifest: {
        heading: 'بيان الاستخراج',
        intro: 'intro',
        rows: [{ label: 'الأداة', value: 'export_report' }],
        json: { tool: 'export_report', note: '</script><script>alert(1)</script>' },
      },
    });
    expect(html).toContain('<th scope="row">الأداة</th><td><bdi>export_report</bdi></td>');
    const json = /<script type="application\/json" id="malja-manifest">(.*)<\/script>/.exec(html)!;
    expect(json[1]).not.toContain('</script>');
    expect(JSON.parse(json[1]!)).toMatchObject({ note: '</script><script>alert(1)</script>' });
  });
});

describe('findBrowser', () => {
  it('honours an explicit path only when it exists, else auto-detects', () => {
    expect(findBrowser('/opt/x/chrome', (p) => p === '/opt/x/chrome')).toBe('/opt/x/chrome');
    expect(findBrowser('/missing', () => false)).toBeUndefined();
    expect(findBrowser(undefined, (p) => p === '/usr/bin/chromium')).toBe('/usr/bin/chromium');
    expect(findBrowser(undefined, () => false)).toBeUndefined();
  });
});

describe('ExportStore', () => {
  it('expires entries after the TTL and evicts the oldest beyond capacity', () => {
    let now = 0;
    const store = new ExportStore(1_000, 2, 1_000_000, () => now);
    const a = store.put('a.html', 'text/html', 'a');
    const b = store.put('b.html', 'text/html', 'b');
    const c = store.put('c.pdf', 'application/pdf', Buffer.from('%PDF-'));
    expect(store.get(a.id)).toBeUndefined();
    expect(store.get(b.id)?.data).toBe('b');
    now = 2_000;
    expect(store.get(c.id)).toBeUndefined();
    expect(store.size).toBe(0);
  });
});
